{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Carbamazepine epoxide, the closest retrieved analogue, has an absolute oral bioavailability of 60% (95% CI 49–75%) in healthy subjects, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Oxcarbazepine, a close dibenzazepine carboxamide analogue, is rapidly and completely absorbed with >95% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Licarbazepine, the active metabolite of oxcarbazepine, has a mean absolute oral bioavailability of 89% after a 300 mg oral dose in healthy adults.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Eslicarbazepine, another close analogue, has >80% oral bioavailability in humans, supporting high absorption for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "PEMA, a lower-similarity carboxamide analogue, has almost complete oral bioavailability of 91 ± 4.4% versus IV in normal volunteers, reinforcing high F for carboxamide-containing molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carbamazepine. All relevant analogues with meaningful transferability—carbamazepine epoxide, oxcarbazepine, licarbazepine, eslicarbazepine, and PEMA—show oral bioavailability well above 20% (60% to >95%). No affirmative evidence supports F <20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct carbamazepine bioavailability record is present in the retrieved evidence set.",
    "Fed-state-specific bioavailability data for carbamazepine are not directly supplied; extrapolation relies on structural analogues and known high absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

